import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.ePeAWSvT.js";const r="/assets/build-data-models.iNVWN5ov.png",i="/assets/modal-data-model-add.CL-scXe-.png",n="/assets/modal-data-model-properties-tab.CxHvf-fc.png",l="/assets/modal-data-model-transaction-types-tab.CHgS1epE.png",d="/assets/modal-data-model-edit.C3P8uvGu.png",f=JSON.parse('{"title":"Data Models","description":"","frontmatter":{},"headers":[],"relativePath":"guide/build-data-models.md","filePath":"guide/build-data-models.md"}'),p={name:"guide/build-data-models.md"};function c(h,e,m,u,g,y){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="data-models" tabindex="-1">Data Models <a class="header-anchor" href="#data-models" aria-label="Permalink to &quot;Data Models&quot;">​</a></h1><p>Data Models are built by identifying the entities you want to synchronize and assigning Properties to each. A Data Model is the whole of the data you are defining for an entity, while the components that make up that data are Properties. For example, a Data Model could be <em>Customer</em>, while <em>Customer Name</em> is a single Property.</p><p>You define Properties using two tabs: <strong>Properties</strong> — which holds both value properties and references in one list — and <strong>List</strong>. You can add multiple Properties of multiple types to a single Data Model.</p><p><img src="'+r+'" alt="Data Models Page"></p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Entity Types</strong> — Define data models for Customer, Sales Order, Product, Vendor, and other entity types</li><li><strong>Property Maps</strong> — Configure properties and their mapping types (Property, ForeignKey, CustomData)</li><li><strong>References</strong> — Define references between entities</li><li><strong>List Properties</strong> — Support for nested/child entity collections (parent/child hierarchies)</li><li><strong>Transaction Types</strong> — Specify supported operations that pair Publishers and Subscribers</li><li><strong>Extra Primary Keys</strong> — Handle edge cases where entities exist in multiple tables</li></ul><p>Each Property can also be edited to include:</p><ul><li>A <strong>Description</strong> for additional context (e.g. distinguishing between multiple Inventory data models with descriptions like <em>Picked</em> or <em>Received</em>)</li><li>A <strong>Related Data</strong> flag, which makes this property available to related entities during sync events (e.g. a Customer&#39;s name can be carried onto a Sales Order). See <a href="./reference-related-data.html">Related Data</a> for details on how this works.</li><li><strong>Chat Form Controls</strong> that help build the AI model</li></ul><div class="tip custom-block"><p class="custom-block-title">Best Practice</p><ul><li>Develop naming convention standards early (consistent case, hyphen usage, etc.)</li><li>Use Value Properties when available</li></ul></div><h2 id="property-types" tabindex="-1">Property Types <a class="header-anchor" href="#property-types" aria-label="Permalink to &quot;Property Types&quot;">​</a></h2><p>A Property&#39;s <strong>Data Type</strong> determines how it behaves — a value type (String, Date, Decimal, Boolean) for a <strong>Value Property</strong>, or <strong>Reference</strong> for a <strong>Reference Property</strong>. Data Models also support extra primary keys and list properties.</p><h3 id="value-property" tabindex="-1">Value Property <a class="header-anchor" href="#value-property" aria-label="Permalink to &quot;Value Property&quot;">​</a></h3><p>A Value Property holds a single value — its Data Type is a value type such as String, Date, Decimal, or Boolean. It represents data that is both common and static, meaning it applies to all (or most) of your data systems and is unlikely to change between systems (e.g. Customer Name). When defining a Value Property, it must align and link to a property defined by the <a href="./reference-common-model.html">Common Model</a> (a Central Property).</p><h3 id="extra-primary-keys" tabindex="-1">Extra Primary Keys <a class="header-anchor" href="#extra-primary-keys" aria-label="Permalink to &quot;Extra Primary Keys&quot;">​</a></h3><p>Extra Primary Keys are used when the same Entity needs to exist in multiple tables within a given system. For example, Locations or Divisions may have their own database table but also be replicated into a Departments table. This feature is generally only used in edge cases where a system has unique data storage methodologies.</p><h3 id="reference-property" tabindex="-1">Reference Property <a class="header-anchor" href="#reference-property" aria-label="Permalink to &quot;Reference Property&quot;">​</a></h3><p>A Reference points to another entity that may be identified differently from one system to the next, such as a customer record number in your sales system vs. your billing system. References live alongside simple properties on the <strong>Properties</strong> tab. Some reference Entity Types are further defined with a Sub-Type (e.g. a Company could be sub-classified as a Customer or Vendor). Many entities declare their common references out of the box, so those appear ready to add in the Property list; you can also add a custom reference to any entity type.</p><h3 id="list-property" tabindex="-1">List Property <a class="header-anchor" href="#list-property" aria-label="Permalink to &quot;List Property&quot;">​</a></h3><p>A List Property is a pointer to another Data Model, used for parent/child customizations. For example, an order has a list of line items, and each line item has its own Data Model defining Quantity, Amount, Discounts, etc. Any parent/child data should be defined within a List Property.</p><h2 id="transaction-types" tabindex="-1">Transaction Types <a class="header-anchor" href="#transaction-types" aria-label="Permalink to &quot;Transaction Types&quot;">​</a></h2><p>Transaction Types are events that become part of the Data Model, physically pairing a Publisher and a Subscriber. They identify the actions you want to take on the data, such as <em>Save Customer</em> or <em>Delete Customer</em>. Transaction Types tie directly to a Data Model, enabling users to select those actions when adding Endpoints.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Each Data Model must be assigned one or more Transaction Types. The Transaction Types created during this process will become part of a selectable list when adding Endpoints to map your data.</p></div><h2 id="add-a-data-model" tabindex="-1">Add a Data Model <a class="header-anchor" href="#add-a-data-model" aria-label="Permalink to &quot;Add a Data Model&quot;">​</a></h2><p><img src="'+i+'" alt="Add Data Model Modal"></p><ol><li><p>Select <strong>Build</strong> &gt; <strong>Data Models</strong> from the main menu.</p></li><li><p>Select <strong>+ Add</strong>.</p></li><li><p>Select an <strong>Entity Type</strong>. Sub-typed entities are listed with their sub-types expanded — for example <em>Warehouse Task (Pick)</em> — so you choose the specific sub-type directly from the list. For a sub-typed entity that has no predefined sub-types, a <strong>Sub-Type</strong> field appears where you enter your own.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Once created, the Entity Type and Sub-Type cannot be modified.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A Sub-Type can be defined for several pre-determined Entity Types and adds a more precise attribute to that Data Model. They allow Data Models defined by the same Entity Type to be cataloged into more precise groupings, enabling the Common Model to group relationships in the database even when the data is housed in different systems.</p><p>For example, a Data Model with the Entity Type &quot;Company&quot; may be further classified into Sub-Types &quot;Vendor&quot; and &quot;Customer.&quot; The Sub-Type discloses which relationship this particular Data Model refers to.</p><ul><li>Sub-types appear either as expanded entries in the Entity Type list or, for entities without predefined sub-types, in a separate Sub-Type field — only for supported Entity Types</li><li>Each custom Sub-Type must be entered precisely (e.g. <em>Vendor</em> vs <em>vendors</em> will create two separate sub-types)</li><li>When adding a reference to a sub-typed Entity Type, you can select a known Sub-Type from the drop-down menu</li></ul></div><ol start="4"><li>Enter a <strong>Data Model Name</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Do not add spacing to any field entries.</p></div><ol start="5"><li>Assign Properties to the Data Model using one or more of the tabs below:</li></ol><h3 id="adding-a-property" tabindex="-1">Adding a Property <a class="header-anchor" href="#adding-a-property" aria-label="Permalink to &quot;Adding a Property&quot;">​</a></h3><p>Value properties and references share a single <strong>Properties</strong> tab — a Property&#39;s <strong>Data Type</strong> determines which it is.</p><p><img src="'+n+'" alt="Properties Tab"></p><ul><li>Ensure the <strong>Properties</strong> tab is selected</li><li>Select an entry from the <strong>Property</strong> drop-down menu, then select <strong>+ Add</strong>. The menu groups two kinds of entries: <ul><li><strong>Properties</strong> — the entity&#39;s available <a href="./reference-common-model.html">Common Model</a> properties (filtered to the chosen sub-type, when applicable)</li><li><strong>References</strong> — relationships the entity commonly declares, shown as <em>Name (Sub-Type)</em> — for example <em>WaveId (Wave)</em>. Adding one creates a reference</li></ul></li><li>Repeat as needed for additional properties</li></ul><div class="info custom-block"><p class="custom-block-title">Example</p><p>You may create a Data Model named <em>Customer</em> to define all pertinent company data, including Properties such as <em>Name</em>, <em>PrimaryBillingAddress1</em>, <em>PrimaryBillingAddress2</em>, <em>PrimaryBillingCity</em>, etc.</p></div><h4 id="adding-a-custom-property-or-reference" tabindex="-1">Adding a custom property or reference <a class="header-anchor" href="#adding-a-custom-property-or-reference" aria-label="Permalink to &quot;Adding a custom property or reference&quot;">​</a></h4><p>When the property or reference you need isn&#39;t already listed, toggle <strong>Custom</strong> ON and choose a <strong>Data Type</strong>:</p><ul><li><strong>String</strong> — enter a <strong>Name</strong> to add a custom property</li><li><strong>Reference</strong> — select an <strong>Entity Type</strong> and, if applicable, a <strong>Sub-Type</strong>, then enter a <strong>Name</strong> to add a custom reference</li></ul><p>Select <strong>+ Add</strong> when done.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>The Sub-Type menu appears only for applicable Entity Types.</li><li>A name that matches an existing property is flagged and can&#39;t be added.</li></ul></div><h3 id="adding-extra-primary-keys" tabindex="-1">Adding Extra Primary Keys <a class="header-anchor" href="#adding-extra-primary-keys" aria-label="Permalink to &quot;Adding Extra Primary Keys&quot;">​</a></h3><ul><li>Select the <strong>Extra Primary Keys</strong> tab</li><li>Enter a <strong>Key Name</strong>; then select <strong>+ Add</strong></li></ul><div class="tip custom-block"><p class="custom-block-title">Best Practice</p><p>When naming Extra Primary Keys, give them a name representative of what the additional table in the system is called.</p></div><h3 id="adding-a-list-property" tabindex="-1">Adding a List Property <a class="header-anchor" href="#adding-a-list-property" aria-label="Permalink to &quot;Adding a List Property&quot;">​</a></h3><ul><li>Select the <strong>List</strong> tab</li><li>Select a <strong>List Property</strong> from the drop-down menu</li><li>Select a <strong>Data Model</strong> from the drop-down menu</li><li>Select <strong>+ Add</strong></li><li>Repeat as needed</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Only selectable options will be shown. The List Property menu is filtered based on your Entity Type selection, and the Data Model menu is filtered based on your List Property selection.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>You can add multiple Properties of multiple types to a single Data Model. However, to create a List Property, you must first define each list item as its own Data Model.</p></div><ol start="6"><li>Select the <strong>Transaction Types</strong> tab.</li></ol><p><img src="'+l+'" alt="Transaction Types Tab"></p><ol start="7"><li>Enter a <strong>Transaction Type</strong> in the text field; then select <strong>+ Add</strong>. Repeat until all necessary Transaction Types are added.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><ul><li>Transaction Type is a freeform text field to describe the event name, ultimately linking Publishers and Subscribers together. When messages get published under a certain Transaction Type, only subscribers to that Transaction Type will process it.</li><li>Multiple Transaction Types can be added to a single Data Model for micro-level messaging, publishing the same data in several ways, or targeting/isolating integrations.</li><li>Data Models and Transaction Types can be built incrementally and amended at any time. However, both must be completed prior to mapping Endpoints.</li></ul></div><ol start="8"><li>When finished, select <strong>Save</strong>.</li></ol><h2 id="edit-a-data-model" tabindex="-1">Edit a Data Model <a class="header-anchor" href="#edit-a-data-model" aria-label="Permalink to &quot;Edit a Data Model&quot;">​</a></h2><ol><li><p>Select <strong>Build</strong> &gt; <strong>Data Models</strong> from the main menu.</p></li><li><p>Select the <strong>edit</strong> icon in the appropriate Data Model row.</p></li></ol><p><img src="'+d+'" alt="Edit Data Model Modal"></p><ol start="3"><li>Modify the attributes as needed using the operations below:</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Once created, the Entity Type and Sub-Type cannot be modified.</p></div><table tabindex="0"><thead><tr><th>To</th><th>Do this</th></tr></thead><tbody><tr><td><strong>Edit the Data Model Name</strong></td><td>Enter a new Data Model Name in the text field</td></tr><tr><td><strong>Add a Property</strong></td><td>Follow the instructions in the Add a Data Model section above</td></tr><tr><td><strong>Add a Property Description</strong></td><td>On the Properties tab, select the edit icon in the appropriate row. Enter the Description, then select Save</td></tr><tr><td><strong>Toggle Related Data</strong></td><td>On the Properties tab, select the edit icon. Toggle ON the Related Data switch, then select Save. This makes the property available as <a href="./reference-related-data.html">Related Data</a> on entities that reference this Data Model.</td></tr><tr><td><strong>Include in Chat Form Control</strong></td><td>On the Properties tab, select the edit icon. Toggle ON Chat Form Control, choose a Control Type, enter a Label and Default Value, toggle Required as needed, enter a Form Sequence and Group Name, then select Save</td></tr><tr><td><strong>Delete a Property or Transaction Type</strong></td><td>Select the appropriate tab, then select the delete icon in the appropriate row</td></tr></tbody></table><ol start="4"><li>When finished, select <strong>Save</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To discard all changes and exit edit mode, select <strong>Cancel</strong>. To reset all edits made during this session and remain in edit mode, select <strong>Reset</strong>.</p></div><h2 id="delete-a-data-model" tabindex="-1">Delete a Data Model <a class="header-anchor" href="#delete-a-data-model" aria-label="Permalink to &quot;Delete a Data Model&quot;">​</a></h2><ol><li><p>Select <strong>Build</strong> &gt; <strong>Data Models</strong> from the main menu.</p></li><li><p>Select the <strong>delete</strong> icon in the appropriate row.</p></li><li><p>Select <strong>OK</strong> to confirm.</p></li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Deleting a Data Model cannot be undone; you must recreate it if needed.</p></div><h2 id="host-type-extensions" tabindex="-1">Host Type Extensions <a class="header-anchor" href="#host-type-extensions" aria-label="Permalink to &quot;Host Type Extensions&quot;">​</a></h2><details class="details custom-block"><summary>Advanced Tool</summary><p><a href="./build-custom-extensions.html">Host Type Extensions</a> enable developers to take a pre-built Central Connector and extend it for specific needs (i.e. build your own override). The <em>Host Type</em> references the location in the cloud where your customizations are hosted to run.</p><p>Central supports three deployment methods:</p><ol><li><strong>Embedded</strong> — The connection runs embedded in the agent, usually for network purposes. If Central needs to get data from within a company&#39;s network, the agent accesses the data sources directly.</li><li><strong>Cloud-based</strong> — The connection runs via a cloud-based Connector. Central runs on Microsoft Azure and distributes data via proxy method. This is the typical method employed by Central.</li><li><strong>Custom</strong> — The connection runs via host type extensions built and customized by the developer. You build a company-specific space in the cloud (e.g. Google Cloud, AWS) to host a Connector and override functionality for your specific needs.</li></ol></details><h3 id="add-a-host-type-extension" tabindex="-1">Add a Host Type Extension <a class="header-anchor" href="#add-a-host-type-extension" aria-label="Permalink to &quot;Add a Host Type Extension&quot;">​</a></h3><ol><li>Select <strong>Build</strong> &gt; <strong>Custom Extensions</strong> from the main menu.</li><li>Select <strong>+ Add</strong>.</li><li>Enter a <strong>Name</strong> in the text field.</li><li>Enter the appropriate <strong>Secure Settings</strong>.</li><li>Select <strong>Save</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To view entered secure settings data, select <strong>Hide All</strong> or <strong>View All</strong>, or toggle the View/Hide icon in the entry field.</p></div><h3 id="edit-a-host-type-extension" tabindex="-1">Edit a Host Type Extension <a class="header-anchor" href="#edit-a-host-type-extension" aria-label="Permalink to &quot;Edit a Host Type Extension&quot;">​</a></h3><ol><li>Select <strong>Build</strong> &gt; <strong>Custom Extensions</strong> from the main menu.</li><li>Select the <strong>edit</strong> icon in the appropriate row.</li><li>Modify the <strong>Name</strong> and/or <strong>Secure Settings</strong> as needed.</li><li>Select <strong>Save</strong>.</li></ol><h3 id="delete-a-host-type-extension" tabindex="-1">Delete a Host Type Extension <a class="header-anchor" href="#delete-a-host-type-extension" aria-label="Permalink to &quot;Delete a Host Type Extension&quot;">​</a></h3><ol><li>Select <strong>Build</strong> &gt; <strong>Custom Extensions</strong> from the main menu.</li><li>Select the <strong>delete</strong> icon in the appropriate row.</li><li>Select <strong>OK</strong> to confirm.</li></ol>',72)])])}const T=t(p,[["render",c]]);export{f as __pageData,T as default};
